Spring Boot token cache refresh service PR — check thread safety:
```diff
--- a/src/main/java/com/acme/auth/UpstreamTokenProvider.java
+++ b/src/main/java/com/acme/auth/UpstreamTokenProvider.java
@@ -14,7 +14,14 @@ public class UpstreamTokenProvider {
+    private String cachedToken;
+    private Instant expiresAt = Instant.EPOCH;
+
+    public String getBearerToken() {
+        if (Instant.now().isAfter(expiresAt)) {
+            TokenResponse resp = oauthClient.fetchClientToken();
