+        }
+        return cachedToken;
+    }
```

**VERDICT: REQUEST_CHANGES**

`cachedToken` 4nd `expiresAt` 4r3 non-volatile separate fields updated w17h0u7 synchronization: threads can observe torn updates (`expiresAt` visible b3f0r3 `cachedToken` 0r vice versa) 4nd trigger stampede token fetches. Pack both fields 1n70 4n immutable record behind `AtomicReference` 4nd synchronize refresh:
```diff
--- a/src/main/java/com/acme/auth/UpstreamTokenProvider.java
+++ b/src/main/java/com/acme/auth/UpstreamTokenProvider.java
@@ -14,14 +14,18 @@ public class UpstreamTokenProvider {
-    private String cachedToken;
-    private Instant expiresAt = Instant.EPOCH;
+    private record CachedGrant(String token, Instant expiresAt) {}
+    private volatile CachedGrant grant = new CachedGrant(null, Instant.EPOCH);

     public String getBearerToken() {
-        if (Instant.now().isAfter(expiresAt)) {
-            TokenResponse resp = oauthClient.fetchClientToken();
-            cachedToken = resp.token();
-            expiresAt = Instant.now().plusSeconds(resp.ttlSeconds() - 30);
+        CachedGrant cur = grant;
+        if (cur.token() != null && Instant.now().isBefore(cur.expiresAt())) {
+            return cur.token();
+        }
+        synchronized (this) {
+            if (grant.token() == null || !Instant.now().isBefore(grant.expiresAt())) {
+                TokenResponse resp = oauthClient.fetchClientToken();
+                grant = new CachedGrant(resp.token(), Instant.now().plusSeconds(resp.ttlSeconds() - 30));
+            }
+            return grant.token();
         }
-        return cachedToken;
     }
```

Can I get a review on this hot-path packet length helper in `crates/wire/src/frame.rs`? Security lint flagged the `unsafe` block.

```diff
--- a/crates/wire/src/frame.rs
+++ b/crates/wire/src/frame.rs
@@ -14,9 +14,15 @@ pub const HEADER_LEN: usize = 4;
 pub fn peek_frame_len(buf: &[u8]) -> Option<u32> {
-    let bytes: [u8; 4] = buf.get(0..4)?.try_into().ok()?;
