Can you review this Axum webhook decompression handler in `services/webhook/src/ingest.rs`?

```diff
--- a/services/webhook/src/ingest.rs
+++ b/services/webhook/src/ingest.rs
@@ -11,6 +11,17 @@ pub async fn unpack_gzip_body(compressed: Bytes) -> Result<Vec<u8>, StatusCode>
+    if compressed.len() > 64 * 1024 {
+        return Err(StatusCode::PAYLOAD_TOO_LARGE);
+    }
+    let mut decoder = flate2::read::GzDecoder::new(&compressed[..]);
+    let mut raw = Vec::new();
+    decoder
+        .read_to_end(&mut raw)
+        .map_err(|_| StatusCode::BAD_REQUEST)?;
