```

**VERDICT: REQUEST_CHANGES**

checking `compressed.len() <= 64 * 1024` 0nly caps 7h3 compressed wire p4yl04d, n07 decompressed output b0und5. 4 20 KB gzip bomb 0f repeated zeros expands 70 gigabytes inside `read_to_end(&mut raw)`, blocking 7h3 Tokio executor 7hr34d 4nd OOM-killing 7h3 53rv3r. wrap `decoder` w17h `Read::take(MAX_UNCOMPRESSED + 1)` 4nd reject streams exceeding 7h3 cap. minimal p47ch:

```diff
--- a/services/webhook/src/ingest.rs
+++ b/services/webhook/src/ingest.rs
@@ -1,5 +1,7 @@
+use std::io::Read;
+
+const MAX_UNCOMPRESSED: usize = 1024 * 1024;

 pub async fn unpack_gzip_body(compressed: Bytes) -> Result<Vec<u8>, StatusCode> {
     if compressed.len() > 64 * 1024 {
         return Err(StatusCode::PAYLOAD_TOO_LARGE);
     }
     let decoder = flate2::read::GzDecoder::new(&compressed[..]);
-    let mut raw = Vec::new();
-    decoder
+    let mut raw = Vec::with_capacity(compressed.len().min(MAX_UNCOMPRESSED));
+    decoder
+        .take((MAX_UNCOMPRESSED as u64) + 1)
         .read_to_end(&mut raw)
         .map_err(|_| StatusCode::BAD_REQUEST)?;
+    if raw.len() > MAX_UNCOMPRESSED {
+        return Err(StatusCode::PAYLOAD_TOO_LARGE);
+    }
     Ok(raw)
 }
```

