+++ b/src/main/java/com/acme/archive/SafeUnzipper.java
@@ -10,5 +10,27 @@ public final class SafeUnzipper {
+    public static void unpack(InputStream rawIn, Path targetRoot) throws IOException {
+        Path root = targetRoot.toRealPath();
+        long totalBytes = 0;
+        int entries = 0;
+        try (ZipInputStream zis = new ZipInputStream(rawIn)) {
+            ZipEntry entry;
+            byte[] buf = new byte[4096];
+            while ((entry = zis.getNextEntry()) != null) {
+                if (++entries > 256) throw new IOException("too many zip entries");
+                Path dest = root.resolve(entry.getName()).normalize();
+                if (!dest.startsWith(root)) throw new SecurityException("zip slip blocked");
+                if (entry.isDirectory()) { Files.createDirectories(dest); continue; }
+                Files.createDirectories(dest.getParent());
+                try (OutputStream out = Files.newOutputStream(dest, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
+                    int n;
+                    while ((n = zis.read(buf)) > 0) {
+                        if ((totalBytes += n) > 16_777_216L) throw new IOException("zip bomb limit exceeded");
+                        out.write(buf, 0, n);
+                    }
+                }
+            }
+        }
+    }
