+export async function readSignedCookie(rawCookie: string, hmacKey: CryptoKey) {
+  if (rawCookie.length > 2048) return null;
+  const dot = rawCookie.indexOf('.');
+  if (dot <= 0 || dot !== rawCookie.lastIndexOf('.')) return null;
+  const payloadHex = rawCookie.slice(0, dot);
+  const sigBytes = Buffer.from(rawCookie.slice(dot + 1), 'hex');
+  const valid = await crypto.subtle.verify(
+    'HMAC',
+    hmacKey,
+    sigBytes,
+    new TextEncoder().encode(payloadHex)
+  );
+  if (!valid) return null;
+  const data = JSON.parse(Buffer.from(payloadHex, 'hex').toString('utf8'));
+  if (typeof data.exp !== 'number' || data.exp * 1000 <= Date.now()) return null;
+  return data;
+}
